import 'dart:convert';

import 'package:dm_tools_app_example/domain/app_user.dart';
import 'package:shared_preferences/shared_preferences.dart';

/// Persists the account to remember between app launches.
///
/// The store holds at most one remembered account: [save] replaces any
/// previous one and [clear] forgets it entirely (sign-out).
abstract class SessionStore {
  /// Remembers [user] across app restarts.
  Future<void> save(AppUser user);

  /// Returns the remembered account, or `null` when none was saved.
  Future<AppUser?> load();

  /// Forgets the remembered account, if any.
  Future<void> clear();
}

/// [SessionStore] backed by `shared_preferences` (local device storage).
class SharedPreferencesSessionStore implements SessionStore {
  /// Creates a store. Tests may inject a [prefs] instance with mock
  /// initial values; production resolves the real one lazily.
  SharedPreferencesSessionStore({SharedPreferences? prefs})
    : _prefsOverride = prefs;

  final SharedPreferences? _prefsOverride;
  SharedPreferences? _prefsCache;

  static const String _storageKey = 'remembered_account';

  Future<SharedPreferences> _prefs() async {
    final SharedPreferences? existing = _prefsOverride ?? _prefsCache;
    if (existing != null) {
      return existing;
    }
    final SharedPreferences resolved = await SharedPreferences.getInstance();
    return _prefsCache = resolved;
  }

  @override
  Future<void> save(AppUser user) async {
    final SharedPreferences prefs = await _prefs();
    await prefs.setString(_storageKey, jsonEncode(user.toJson()));
  }

  @override
  Future<AppUser?> load() async {
    final SharedPreferences prefs = await _prefs();
    final String? raw = prefs.getString(_storageKey);
    if (raw == null) {
      return null;
    }
    return AppUser.fromJson(jsonDecode(raw) as Map<String, dynamic>);
  }

  @override
  Future<void> clear() async {
    final SharedPreferences prefs = await _prefs();
    await prefs.remove(_storageKey);
  }
}

/// In-memory [SessionStore] for tests and previews; nothing survives the
/// process lifetime.
class InMemorySessionStore implements SessionStore {
  AppUser? _user;

  @override
  Future<void> save(AppUser user) async {
    _user = user;
  }

  @override
  Future<AppUser?> load() async {
    return _user;
  }

  @override
  Future<void> clear() async {
    _user = null;
  }
}

import 'package:dm_tools_app_example/services/session_controller.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:sign_in_with_apple/sign_in_with_apple.dart';

/// Whether the current platform supports Apple sign-in.
///
/// Platform convention per the ticket: Apple on Apple devices only,
/// Google everywhere.
bool get appleSignInAvailable {
  return defaultTargetPlatform == TargetPlatform.iOS ||
      defaultTargetPlatform == TargetPlatform.macOS;
}

/// Login page: social sign-in buttons plus the remember-me toggle.
class LoginPage extends StatefulWidget {
  const LoginPage({super.key, required this.controller});

  final SessionController controller;

  @override
  State<LoginPage> createState() => _LoginPageState();
}

class _LoginPageState extends State<LoginPage> {
  bool _rememberMe = false;

  void _signIn(Future<void> Function({required bool remember}) flow) {
    flow(remember: _rememberMe);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: SafeArea(
        child: ListenableBuilder(
          listenable: widget.controller,
          builder: (BuildContext context, Widget? _) {
            final SessionController controller = widget.controller;
            final bool busy = controller.busy;

            return Center(
              child: ConstrainedBox(
                constraints: const BoxConstraints(maxWidth: 360),
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 24),
                  child: Column(
                    mainAxisAlignment: MainAxisAlignment.center,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: <Widget>[
                      Icon(
                        Icons.lock_outline,
                        size: 56,
                        color: Theme.of(context).colorScheme.primary,
                      ),
                      const SizedBox(height: 16),
                      Text(
                        'Sign in to continue',
                        textAlign: TextAlign.center,
                        style: Theme.of(context).textTheme.headlineSmall,
                      ),
                      const SizedBox(height: 32),
                      OutlinedButton.icon(
                        key: const Key('google_sign_in_button'),
                        onPressed: busy
                            ? null
                            : () => _signIn(controller.signInWithGoogle),
                        icon: const _GoogleGlyph(),
                        label: const Text('Sign in with Google'),
                      ),
                      if (appleSignInAvailable) ...<Widget>[
                        const SizedBox(height: 12),
                        SignInWithAppleButton(
                          onPressed: busy
                              ? null
                              : () => _signIn(controller.signInWithApple),
                          style: SignInWithAppleButtonStyle.black,
                          height: 48,
                        ),
                      ],
                      SwitchListTile(
                        key: const Key('remember_me_toggle'),
                        title: const Text('Remember me'),
                        subtitle: const Text('Stay signed in on this device'),
                        value: _rememberMe,
                        onChanged: busy
                            ? null
                            : (bool value) =>
                                  setState(() => _rememberMe = value),
                      ),
                      if (busy) ...<Widget>[
                        const SizedBox(height: 24),
                        const Center(
                          child: SizedBox(
                            key: Key('login_progress'),
                            width: 28,
                            height: 28,
                            child: CircularProgressIndicator(strokeWidth: 3),
                          ),
                        ),
                      ],
                      if (controller.error != null) ...<Widget>[
                        const SizedBox(height: 16),
                        Text(
                          key: const Key('login_error_text'),
                          'Sign-in failed: ${controller.error}',
                          textAlign: TextAlign.center,
                          style: TextStyle(
                            color: Theme.of(context).colorScheme.error,
                          ),
                        ),
                      ],
                    ],
                  ),
                ),
              ),
            );
          },
        ),
      ),
    );
  }
}

/// Minimal brand mark for the Google button (single-color "G" glyph).
class _GoogleGlyph extends StatelessWidget {
  const _GoogleGlyph();

  @override
  Widget build(BuildContext context) {
    return const Text(
      'G',
      style: TextStyle(
        fontSize: 18,
        fontWeight: FontWeight.w700,
        color: Color(0xFF4285F4),
      ),
    );
  }
}

import 'package:dm_tools_app_example/domain/app_user.dart';
import 'package:dm_tools_app_example/services/session_controller.dart';
import 'package:flutter/material.dart';

/// Page shown while an account is signed in: profile details and sign-out.
class HomePage extends StatelessWidget {
  const HomePage({super.key, required this.controller});

  final SessionController controller;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Home'),
        actions: <Widget>[
          IconButton(
            key: const Key('sign_out_button'),
            tooltip: 'Sign out',
            icon: const Icon(Icons.logout),
            onPressed: () => controller.signOut(),
          ),
        ],
      ),
      body: ListenableBuilder(
        listenable: controller,
        builder: (BuildContext context, Widget? _) {
          final AppUser? user = controller.user;
          if (user == null) {
            return const SizedBox.shrink();
          }

          return Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: <Widget>[
                CircleAvatar(
                  radius: 40,
                  child: Text(
                    _initialFor(user),
                    style: Theme.of(context).textTheme.headlineMedium,
                  ),
                ),
                const SizedBox(height: 16),
                Text(
                  _displayNameFor(user),
                  style: Theme.of(context).textTheme.titleLarge,
                ),
                if (user.email != null) ...<Widget>[
                  const SizedBox(height: 4),
                  Text(user.email!),
                ],
                const SizedBox(height: 8),
                Text(
                  'Signed in with ${user.provider.name}',
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  String _displayNameFor(AppUser user) {
    if (user.displayName != null && user.displayName!.trim().isNotEmpty) {
      return user.displayName!;
    }
    return switch (user.provider) {
      AuthProvider.google => 'Google account',
      AuthProvider.apple => 'Apple account',
    };
  }

  String _initialFor(AppUser user) {
    final String? name = user.displayName;
    if (name != null && name.trim().isNotEmpty) {
      return name.trim()[0].toUpperCase();
    }
    return switch (user.provider) {
      AuthProvider.google => 'G',
      AuthProvider.apple => '',
    };
  }
}

