  _RecordingStore({this.initial});

  final AppUser? initial;
  AppUser? saved;
  bool cleared = false;

  @override
  Future<void> clear() async {
    cleared = true;
    saved = null;
  }

  @override
  Future<AppUser?> load() async => cleared ? null : saved ?? initial;

  @override
  Future<void> save(AppUser user) async {
    saved = user;
  }
}

