      const user = AppUser(id: 'u', provider: AuthProvider.apple);
      final InMemorySessionStore store = InMemorySessionStore();

      expect(await store.load(), isNull);

      await store.save(user);
      expect(await store.load(), equals(user));

      await store.clear();
      expect(await store.load(), isNull);
    });
  });
}

